def square_areas(sides)
  result = []
  sides.each { |s| result << s * s }
  result
end

n = gets.to_i
raw = gets.split
sides = []
raw.each { |x| sides << x.to_i }
puts square_areas(sides).join(" ")

def keep_evens(nums)
  result = []
  nums.each { |x| result << x if x.even? }
  result
end

n = gets.to_i
raw = gets.split
nums = []
raw.each { |x| nums << x.to_i }
puts keep_evens(nums).join(" ")
